  \node[above right] at (vB) {$B$};
  \node[below right] at (vC) {$C$};
  \node[below left] at (vD) {$D$};
  \node[brand,font=\scriptsize] at (1.05,1.55) {$115^\circ$};
\end{tikzpicture}
}
\par\vspace{2pt}{\sffamily\scriptsize\itshape\color{muted}Ví dụ 1}
\end{minipage}

\par\nopagebreak
\begin{minipage}[t]{0.62\linewidth}\vspace{0pt}
\textbf{Ví dụ 2.} Cho tam giác $ABC$ cân tại $A$. Trên các cạnh $AB, AC$ lần lượt lấy các điểm $D, E$ sao cho $AD = AE$. Chứng minh tứ giác $BDEC$ là hình thang cân.[[br]]{\sffamily\bfseries\color{brand}Lời giải}[[br]]\hspace*{1.4em}Vì $\triangle ABC$ cân tại $A$ nên $\widehat{B} = \dfrac{180^\circ - \widehat{A}}{2}$.[[br]]\hspace*{1.4em}Vì $AD = AE$ nên $\triangle ADE$ cân tại $A$, suy ra $\widehat{ADE} = \dfrac{180^\circ - \widehat{A}}{2}$.[[br]]\hspace*{1.4em}Do đó $\widehat{ADE} = \widehat{B}$. Mà hai góc này ở vị trí đồng vị nên $DE \parallel BC$.[[br]]\hspace*{1.4em}Tứ giác $BDEC$ có $DE \parallel BC$ nên là hình thang.[[br]]\hspace*{1.4em}Hình thang $BDEC$ có hai góc kề đáy $\widehat{B} = \widehat{C}$ (do $\triangle ABC$ cân tại $A$) nên $BDEC$ là hình thang cân.[[br]]\hspace*{1.4em}Vậy $BDEC$ là hình thang cân.
\end{minipage}\hfill
